// Open Deploy: the door's one entry, and the only place it names itself. The webhook is the ONLY
// way in (Operator ruling 2026-09-03): Schedule Live View Deploys creates the launch row and fires
// this webhook, so a scheduled deploy and a hand launch are the same run.
// Email Bison is hardcoded to DuoDiv's instance (Operator ruling 2026-09-06): the base URL sits on
// the HTTP nodes and the token on their credential; no registry field names either.
const b = ($input.first() || {}).json || {};
const recordId = String((b.body && b.body.recordId) || (b.query && b.query.recordId) || b.recordId || '').trim();
return [{ json: {
  mode: 'prepare',
  sender: 'Email Bison',
  automation: 'Deploy View to Email Bison Campaign',
  execId: String($execution.id),
  wfId: String($workflow.id),
  recordId: recordId || 'recMISSING'
} }];

// Load State: what prepare resolved becomes this run's state. It lives in static data for the
// length of the send lane only, because the chunk loop's Wait is seconds long and keeps the
// execution in memory; Close Deploy takes it back off and hands it to finish as data.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id;
const p = ($input.first() || {}).json || {};
const D = p.state || {};
sd[dk] = D;
return [{ json: { target: D.target || '', ready: !!p.ready, abort: !!D.abort, body: p.body || null } }];

// Check Bison Campaign: the target must exist on the instance, proven by GET /api/campaigns/{id},
// before a single lead is created. The Hub row is only the description of a campaign, not proof
// that it is there. The name Bison itself carries wins for the run log and the receipt, and the
// campaign's status is kept: attach-leads on an ACTIVE campaign is cached and synced every five
// minutes on Bison's side, so the read-back has to wait that out before it may call a lead missing.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id; const D = sd[dk];
const p = $('Load State').first().json;
if (!D.abort) {
  const j = ($input.first() || {}).json || {};
  const hasWrap = Object.prototype.hasOwnProperty.call(j, 'body');
  const rb = hasWrap ? j.body : j;
  const status = Number(j.statusCode || 0);
  const c = rb && rb.data && typeof rb.data === 'object' ? rb.data : null;
  if (j.error && !hasWrap && !status) {
    D.abort = 'campaign check failed'; D.errors.push('GET campaign ' + D.target + ' errored before a response: ' + String(j.error).slice(0, 200) + '; nothing was sent');
  } else if (status === 404 || !c || String(c.id) !== String(D.target)) {
    D.abort = 'campaign not found'; D.errors.push('campaign ' + D.target + ' not found on the Email Bison instance (HTTP ' + (status || '?') + '); nothing was sent');
  } else if (status && (status < 200 || status >= 300)) {
    D.abort = 'campaign check failed'; D.errors.push('GET campaign ' + D.target + ' answered HTTP ' + status + ': ' + JSON.stringify(rb).slice(0, 200) + '; nothing was sent');
  } else {
    D.campName = c.name || D.campName || D.target;
    D.bisonStatus = String(c.status || '');
    D.bisonActive = D.bisonStatus === 'active';
    if (D.bisonStatus === 'archived') { D.abort = 'campaign archived'; D.errors.push('campaign "' + D.campName + '" is archived on Email Bison; nothing was sent'); }
  }
}
const ready = !D.abort && !!p.ready;
return [{ json: { kind: 'create', ready: ready, abort: !!D.abort, body: ready ? p.body : null, wait: 0, target: D.target || '' } }];

// Collect Create: the response of one create-or-update chunk. Bison returns every lead it now
// holds for the chunk, with ids; a lead it dropped (a personal domain, an address it judged
// invalid) is simply absent, so the emails that came back are compared with the emails sent and
// the rest are skipped by name. The ids go to Attach as the next call of the loop; nothing here
// advances the queue, Collect Attach does that once the chunk is really in the campaign.
// Counters ride in D.pv on purpose: the shared Build Run Log reads them for every email sender.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id; const D = sd[dk]; const S = D.send;
const j = ($input.first() || {}).json || {};
const hasWrap = Object.prototype.hasOwnProperty.call(j, 'body');
const rb = hasWrap ? j.body : j;
const status = Number(j.statusCode || 0);
D.pv = D.pv || { sent: 0, uploaded: 0, duplicate: 0, already: 0, invalid: 0, skipped: 0, overwritten: 0, overflowed: 0, remaining: null };
D.bisonIds = D.bisonIds || [];
const P = D.pv;
const cur = S.queue[S.idx] || [];
const mkCreate = (chunk) => Object.assign({ leads: chunk }, D.flags || {});
const out = (o) => [{ json: Object.assign({ target: D.target || '' }, o) }];
const advance = () => {
  if (S.idx < S.queue.length) S.queue[S.idx] = null;
  S.idx++; S.attempts = 0;
  if (S.idx < S.queue.length && S.queue[S.idx]) return out({ kind: 'create', body: mkCreate(S.queue[S.idx]), wait: 2 });
  return out({ done: true, wait: 0 });
};
const skipRow = (email, why) => { const rid = D.emailToRow[String(email || '').toLowerCase()]; if (rid && D.rows[rid] && !D.rows[rid].skip) D.rows[rid].skip = why; };
if (j.error && !hasWrap && !status) {
  // The HTTP node itself errored (no request went out). Retry the same chunk, capped.
  S.attempts++;
  if (S.attempts <= 3 && cur.length) return out({ kind: 'create', body: mkCreate(cur), wait: Math.pow(2, S.attempts) });
  D.errors.push('create chunk ' + (S.idx + 1) + '/' + S.queue.length + ' node error: ' + String(j.error).slice(0, 200));
  for (const l of cur) skipRow(l.email, 'create call failed');
  return advance();
}
const arr = rb && Array.isArray(rb.data) ? rb.data : null;
if (status >= 200 && status < 300 && arr) {
  S.attempts = 0;
  P.sent += cur.length;
  const back = {};
  for (const l of arr) { const e = String(l.email || '').toLowerCase().trim(); if (e && l.id) back[e] = l.id; }
  const ids = [];
  for (const l of cur) {
    const e = String(l.email || '').toLowerCase().trim();
    if (back[e]) { ids.push(back[e]); D.bisonIds.push({ id: back[e], email: e }); }
    else { P.invalid++; skipRow(e, 'skipped by Email Bison at create (personal domain or invalid address)'); }
  }
  D.pendingIds = ids;
  if (!ids.length) return advance();
  return out({ kind: 'attach', body: { lead_ids: ids, allow_parallel_sending: false }, wait: 2 });
}
// Laravel-style validation: 422 with errors keyed "leads.<index>.<field>". Drop those rows, resend the rest.
if (status === 422 && rb && rb.errors && typeof rb.errors === 'object') {
  const bad = {};
  for (const k of Object.keys(rb.errors)) { const m = /^leads\.(\d+)\./.exec(k); if (m) bad[Number(m[1])] = String((rb.errors[k] || [])[0] || k).slice(0, 120); }
  const idxs = Object.keys(bad);
  if (idxs.length) {
    const keep = [];
    cur.forEach((l, i) => {
      if (bad[i] !== undefined) { D.errors.push('lead rejected by Email Bison validation, dropped: ' + (l.email || ('index ' + i)) + ' (' + bad[i] + ')'); skipRow(l.email, 'rejected by Email Bison validation'); }
      else keep.push(l);
    });
    if (keep.length) { S.queue[S.idx] = keep; return out({ kind: 'create', body: mkCreate(keep), wait: 2 }); }
    return advance();
  }
}
const bs = JSON.stringify(rb || {}).toLowerCase();
if ((status === 413 || status === 400) && cur.length > 25 && /too large|payload|entity|body size|request size/.test(bs)) {
  const half = Math.ceil(cur.length / 2);
  const a = cur.slice(0, half), b = cur.slice(half);
  S.queue.splice(S.idx, 1, a, b);
  return out({ kind: 'create', body: mkCreate(a), wait: 2 });
}
S.attempts++;
if (S.attempts <= 3 && cur.length) {
  let w = Math.pow(2, S.attempts);
  const h = j.headers || {}; const ra = Number(h['retry-after'] || h['Retry-After'] || 0); if (ra > 0) w = Math.max(w, Math.min(ra, 120));
  return out({ kind: 'create', body: mkCreate(cur), wait: w });
}
D.errors.push('create chunk ' + (S.idx + 1) + '/' + S.queue.length + ' failed after 3 retries (status ' + (status || '?') + '): ' + JSON.stringify(rb).slice(0, 200));
for (const l of cur) skipRow(l.email, 'create call failed');
return advance();

// Collect Attach: the response of attach-leads for the chunk Collect Create just created. A 200
// with success:true means the campaign accepted the ids (on an active campaign Bison caches them
// and syncs within five minutes; the read-back waits for that). Attach is the step that advances
// the queue: the next item is the next chunk's create body, or done.
// Live progress is written to the launch row after every chunk (Stamp Progress hangs off this
// output as a SIDE branch; it must never sit between this node and Send Done?).
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id; const D = sd[dk]; const S = D.send;
const j = ($input.first() || {}).json || {};
const hasWrap = Object.prototype.hasOwnProperty.call(j, 'body');
const rb = hasWrap ? j.body : j;
const status = Number(j.statusCode || 0);
const P = D.pv || (D.pv = { sent: 0, uploaded: 0, duplicate: 0, already: 0, invalid: 0, skipped: 0, overwritten: 0, overflowed: 0, remaining: null });
const ids = D.pendingIds || [];
const fmt = v => Number(v || 0).toLocaleString('en-US');
const mkCreate = (chunk) => Object.assign({ leads: chunk }, D.flags || {});
const emit = (o) => {
  const total = S.queue.length || 1; const doneChunks = Math.min(S.idx, total);
  const lines = ['**Uploading to ' + (D.campName || '?') + '**', '', '- Chunk ' + fmt(doneChunks) + ' of ' + fmt(total), '- Sent so far: ' + fmt(P.sent), '- Accepted so far: ' + fmt(P.uploaded)];
  if (P.invalid) lines.push('- Skipped by Email Bison at create (personal domain or invalid): ' + fmt(P.invalid));
  lines.push('', 'Read-back and the full report follow once uploading finishes.');
  return [{ json: Object.assign({ _lid: D.launchId || '', _prog: lines.join('\n'), target: D.target || '' }, o) }];
};
const advance = () => {
  D.pendingIds = [];
  if (S.idx < S.queue.length) S.queue[S.idx] = null;
  S.idx++; S.attempts = 0;
  if (S.idx < S.queue.length && S.queue[S.idx]) return emit({ kind: 'create', body: mkCreate(S.queue[S.idx]), wait: 2 });
  return emit({ done: true, wait: 0 });
};
const retryOrGiveUp = (why) => {
  S.attempts++;
  if (S.attempts <= 3 && ids.length) {
    let w = Math.pow(2, S.attempts);
    const h = j.headers || {}; const ra = Number(h['retry-after'] || h['Retry-After'] || 0); if (ra > 0) w = Math.max(w, Math.min(ra, 120));
    return emit({ kind: 'attach', body: { lead_ids: ids, allow_parallel_sending: false }, wait: w });
  }
  D.errors.push('attach-leads for chunk ' + (S.idx + 1) + '/' + S.queue.length + ' failed after 3 retries: ' + why);
  // The leads exist on Bison but never reached the campaign; the read-back will find them missing
  // and the stamp says so per row. Nothing is counted as accepted.
  return advance();
};
if (j.error && !hasWrap && !status) return retryOrGiveUp('node error: ' + String(j.error).slice(0, 200));
const ok = status >= 200 && status < 300 && rb && rb.data && rb.data.success !== false;
if (ok) { P.uploaded += ids.length; D.uploadedNew += ids.length; return advance(); }
return retryOrGiveUp('HTTP ' + (status || '?') + ' ' + JSON.stringify(rb).slice(0, 200));

// Init Readback: the proof pass. Every id created this run is read back one by one from
// GET /api/leads/{id}, and a lead counts as deployed only when its lead_campaign_data names this
// campaign. Bison caches attach-leads on an ACTIVE campaign and syncs every five minutes, so on an
// active campaign the first read waits 320 seconds; a paused or draft campaign attaches at once.
// Bison lists are 15 to a page with no page-size control, which is why the read-back is by id and
// never a walk of the campaign.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id; const D = sd[dk];
const ids = D.bisonIds || [];
D.rb = { idx: 0, attempts: 0 };
if (!ids.length) return [{ json: { done: true, wait: 0 } }];
return [{ json: { lead_id: ids[0].id, wait: D.bisonActive ? 320 : 5 } }];

// Collect RB: one lead read back. Membership = lead_campaign_data contains this campaign's id.
// A non-2xx answer is retried with backoff (Retry-After honoured) up to five times, then the
// read-back is marked failed and the unconfirmed rows stay unstamped, exactly as on PlusVibe.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id; const D = sd[dk]; const R = D.rb;
const ids = D.bisonIds || [];
const j = ($input.first() || {}).json || {};
const hasWrap = Object.prototype.hasOwnProperty.call(j, 'body');
const body = hasWrap ? j.body : j;
const status = Number(j.statusCode || 0);
const emit = o => [{ json: o }];
const next = () => {
  R.idx++; R.attempts = 0;
  if (R.idx < ids.length) return emit({ lead_id: ids[R.idx].id, wait: 1 });
  return emit({ done: true, wait: 0 });
};
const lead = body && body.data && typeof body.data === 'object' ? body.data : null;
if ((status && (status < 200 || status >= 300)) || !lead || (j.error && !hasWrap && !status)) {
  R.attempts++;
  if (R.attempts <= 5) {
    let w = Math.pow(2, R.attempts);
    const h = j.headers || {}; const ra = Number(h['retry-after'] || h['Retry-After'] || 0); if (ra > 0) w = Math.max(w, Math.min(ra, 120));
    return emit({ lead_id: ids[R.idx].id, wait: w });
  }
  D.rbFailed = true;
  D.errors.push('read-back failed at lead ' + (R.idx + 1) + '/' + ids.length + ' (id ' + ids[R.idx].id + ') after 5 retries (status ' + (status || '?') + '); unconfirmed rows left unstamped');
  return emit({ done: true, wait: 0 });
}
const want = String(D.target);
const camps = Array.isArray(lead.lead_campaign_data) ? lead.lead_campaign_data : [];
const member = camps.some(c => c && String(c.campaign_id) === want);
const e = String(lead.email || ids[R.idx].email || '').toLowerCase().trim();
if (member && e) D.inCamp[e] = 1;
return next();

// Close Deploy: the send lane is over; everything it learned goes back to the shared machine,
// which stamps the source rows, writes the receipt and writes the run's Hub row. The state leaves
// static data here so nothing of this run is left behind in the workflow.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id;
const D = sd[dk] || { errors: ['deploy state missing'], warnings: [], rows: {}, skipCounts: {}, launchId: '', sender: 'Email Bison' };
delete sd[dk];
D.bisonIds = null; D.pendingIds = null;
return [{ json: {
  mode: 'finish',
  sender: 'Email Bison',
  automation: 'Deploy View to Email Bison Campaign',
  execId: String($execution.id),
  wfId: String($workflow.id),
  state: D
} }];
